import { path } from '@servicenow/sdk-build-core'
import { Project } from '../../src'
import { rmSync } from 'fs'

describe('SourceFile tests', () => {
    const baseDir = path.join(__dirname, 'sourcefile_tests')
    const randomString = () => Math.random().toString(36).substring(2)
    const createFolderName = () => path.join(baseDir, randomString())

    afterAll(() => {
        rmSync(baseDir, { recursive: true, force: true })
    })

    test(`does not format non .ts files, such as .css files`, async () => {
        const rootDir = createFolderName()
        const project = new Project({
            rootDir,
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        const css = `.my-class {
    background: red;
}
`
        const cssFile = project.addFile({ path: 'src/fluent/generated/my-widget.css', content: css })
        project.save()
        cssFile.reload()

        expect(cssFile.getContent()).toEqual(css)
    })

    test(`format should remove unused code`, async () => {
        const rootDir = createFolderName()
        const project = new Project({
            rootDir,
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        const code = `import { Role } from '@servicenow/sdk/core'

// this is a comment
const role = Role({
    $id: 'aa65002f07426110f736e28f69d300f5',
    name: 'x_example_app.role',
})

/* this is also a comment */
const role2 = Role({
    $id: 'aa65002f07426110f736e28f69d300f6',
    name: 'x_example_app.role2',
})

/* 
* this is also a comment 
*/
const role3 = Role({
    $id: 'aa65002f07426110f736e28f69d300f7',
    name: 'x_example_app.role3',
})
`
        const fluentFile = project.addFile({ path: 'src/fluent/generated/index.now.ts', content: code })
        await project.fix()
        project.save()
        fluentFile.reload()
        expect(fluentFile.getContent()).toEqual(`import { Role } from '@servicenow/sdk/core'

// this is a comment
Role({
    $id: 'aa65002f07426110f736e28f69d300f5',
    name: 'x_example_app.role',
})

/* this is also a comment */
Role({
    $id: 'aa65002f07426110f736e28f69d300f6',
    name: 'x_example_app.role2',
})

/* 
* this is also a comment 
*/
Role({
    $id: 'aa65002f07426110f736e28f69d300f7',
    name: 'x_example_app.role3',
})
`)
    })
})
